static void set_mem_access(MCInst *MI, bool status)
{
        if (MI->csh->detail != CS_OPT_ON)
                return;

        MI->csh->doing_mem = status;
        if (!status)
                // done, create the next operand slot
                MI->flat_insn->detail->x86.op_count++;

}

